+++ b/packages/workflow/test/errors/frozen-error-prototype.test.ts
@@ -0,0 +1,33 @@
+import { ExecutionBaseError } from '../../src/errors/abstract/execution-base.error';
+import { SubworkflowOperationError } from '../../src/errors/subworkflow-operation.error';
+import { WorkflowOperationError } from '../../src/errors/workflow-operation.error';
+
+describe('execution errors when Error.prototype is frozen', () => {
+	beforeAll(() => {
+		// In the secure-mode task-runner sandbox the built-in prototypes are frozen.
+		// Plain assignment to an inherited read-only property (e.g. `name`) throws
+		// in strict mode, so errors must define their own properties instead.
+		Object.freeze(Error.prototype);
+	});
+
+	it('constructs an ExecutionBaseError subclass with its class name', () => {
+		class CustomExecutionError extends ExecutionBaseError {}
+		const error = new CustomExecutionError('boom');
+		expect(error.name).toBe('CustomExecutionError');
+		expect(error.message).toBe('boom');
+	});
+
+	it('constructs a WorkflowOperationError with its class name', () => {
+		const error = new WorkflowOperationError('timed out');
+		expect(error.name).toBe('WorkflowOperationError');
+		expect(error.message).toBe('timed out');
+		expect(error.level).toBe('warning');
+	});
+
+	it('constructs a SubworkflowOperationError with its class name and cause', () => {
+		const error = new SubworkflowOperationError('failed', 'details');
+		expect(error.name).toBe('SubworkflowOperationError');
+		expect(error.description).toBe('details');
+		expect(error.cause).toMatchObject({ name: 'SubworkflowOperationError', message: 'failed' });
+	});
+});
